-- 글마당 예시 글 (자동 생성: deploy/seed/build_seed.py, 원본 deploy/seed/board.json). 손으로 고치지 않는다
-- demo-content.sql 다음에 실행한다. 몇 번 실행해도 같다 (이미 있는 글·댓글은 넣지 않는다)
\set ON_ERROR_STOP on
\if :{?schema}
\else
\set schema public
\endif
set search_path = :"schema";
begin;
do $$ begin
  if not exists (select 1 from users where password = '!demo-account-no-login' and email like 'demo.%@example.com') then
    raise exception '예시 데이터가 없습니다. 먼저 demo-content.sql을 실행하세요';
  end if;
end $$;

-- 부산 1박 2일인데 비 소식이 있어요. 실내로 갈 만한 곳 있을까요?
insert into board_post (users_id, topic_id, kind, title, content, views, comment_count, created_at, updated_at) select u.users_id, t.topic_id, 'question', '부산 1박 2일인데 비 소식이 있어요. 실내로 갈 만한 곳 있을까요?', '이번 주 금요일 저녁에 내려가서 토요일 밤에 올라오는 일정이에요. 그런데 토요일 오후 내내 비 예보가 떴습니다.

- 해운대·광안리 쪽에 숙소를 잡아 뒀어요
- 차 없이 지하철·버스로 움직입니다
- 시장 구경은 좋아하는데 쇼핑몰은 별로예요

비 오는 부산에서 반나절 보내기 좋았던 곳 있으면 알려 주세요!', 142, 0, now() - interval '5 hours', now() - interval '5 hours' from users u, topic t where u.email = 'demo.halfday@example.com' and t.topic_name = '여행' and not exists (select 1 from board_post bp where bp.users_id = u.users_id and bp.title = '부산 1박 2일인데 비 소식이 있어요. 실내로 갈 만한 곳 있을까요?');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '영도 흰여울 문화마을 쪽 카페들이 비 오는 날 더 좋아요. 창밖으로 바다에 비 내리는 게 보여서 한참 앉아 있게 됩니다. 남포동에서 버스로 금방이에요.', bp.created_at + interval '18 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.halfday@example.com' and bp.title = '부산 1박 2일인데 비 소식이 있어요. 실내로 갈 만한 곳 있을까요?' and u.email = 'demo.sea@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '영도 흰여울 문화마을 쪽 카페들이 비 오는 날 더 좋아요. 창밖으로 바다에 비 내리는 게 보여서 한참 앉아 있게 됩니다. 남포동에서 버스로 금방이에요.');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '부산근현대역사관 추천해요. 옛 은행 건물이라 사진 찍기도 좋고, 나와서 바로 보수동 책방골목까지 걸을 수 있어요(비가 약하면요).', bp.created_at + interval '52 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.halfday@example.com' and bp.title = '부산 1박 2일인데 비 소식이 있어요. 실내로 갈 만한 곳 있을까요?' and u.email = 'demo.film@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '부산근현대역사관 추천해요. 옛 은행 건물이라 사진 찍기도 좋고, 나와서 바로 보수동 책방골목까지 걸을 수 있어요(비가 약하면요).');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '부평깡통시장은 지붕이 있어서 비 와도 괜찮아요. 어묵이랑 유부주머니 꼭 드세요 😋', bp.created_at + interval '95 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.halfday@example.com' and bp.title = '부산 1박 2일인데 비 소식이 있어요. 실내로 갈 만한 곳 있을까요?' and u.email = 'demo.mukja@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '부평깡통시장은 지붕이 있어서 비 와도 괜찮아요. 어묵이랑 유부주머니 꼭 드세요 😋');
update board_post set comment_count = (select count(*) from board_comment c where c.board_post_id = board_post.board_post_id) where board_post_id = (select bp.board_post_id from board_post bp join users a on a.users_id = bp.users_id where a.email = 'demo.halfday@example.com' and bp.title = '부산 1박 2일인데 비 소식이 있어요. 실내로 갈 만한 곳 있을까요?');
update board_post set accepted_comment_id = (select c.board_comment_id from board_comment c join users u on u.users_id = c.users_id where c.board_post_id = board_post.board_post_id and u.email = 'demo.sea@example.com' and c.content = '영도 흰여울 문화마을 쪽 카페들이 비 오는 날 더 좋아요. 창밖으로 바다에 비 내리는 게 보여서 한참 앉아 있게 됩니다. 남포동에서 버스로 금방이에요.') where board_post_id = (select bp.board_post_id from board_post bp join users a on a.users_id = bp.users_id where a.email = 'demo.halfday@example.com' and bp.title = '부산 1박 2일인데 비 소식이 있어요. 실내로 갈 만한 곳 있을까요?') and accepted_comment_id is null;

-- 퇴근하고 20분 안에 만드는 저녁, 다들 뭐 드세요?
insert into board_post (users_id, topic_id, kind, title, content, views, comment_count, created_at, updated_at) select u.users_id, t.topic_id, 'talk', '퇴근하고 20분 안에 만드는 저녁, 다들 뭐 드세요?', '요즘 제 1번은 **두부 김치 볶음**이에요. 김치랑 돼지고기 볶는 동안 두부를 데우면 15분이면 끝나요.

2번은 냉동 새우 넣은 마늘 파스타. 면 삶는 물 끓이는 동안 마늘 썰면 시간이 딱 맞습니다.

여러분의 ''퇴근 20분 메뉴''를 하나씩 남겨 주세요. 다음 주 장보기 목록 만들려고요!', 211, 0, now() - interval '9 hours', now() - interval '9 hours' from users u, topic t where u.email = 'demo.homecook@example.com' and t.topic_name = '음식' and not exists (select 1 from board_post bp where bp.users_id = u.users_id and bp.title = '퇴근하고 20분 안에 만드는 저녁, 다들 뭐 드세요?');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '닭가슴살 스테이크에 양배추 채 썰어서 같이 구워요. 달리고 온 날은 이거 하나면 충분해요.', bp.created_at + interval '22 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.homecook@example.com' and bp.title = '퇴근하고 20분 안에 만드는 저녁, 다들 뭐 드세요?' and u.email = 'demo.runner@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '닭가슴살 스테이크에 양배추 채 썰어서 같이 구워요. 달리고 온 날은 이거 하나면 충분해요.');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '주말에 구워 둔 식빵으로 에그 샌드위치요. 계란만 삶으면 10분이에요 🍞', bp.created_at + interval '40 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.homecook@example.com' and bp.title = '퇴근하고 20분 안에 만드는 저녁, 다들 뭐 드세요?' and u.email = 'demo.bakery@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '주말에 구워 둔 식빵으로 에그 샌드위치요. 계란만 삶으면 10분이에요 🍞');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '냉동실에 볶음밥 소스를 얼음틀에 얼려 두면 밥만 볶으면 돼요. 이거 하고 나서 배달이 반으로 줄었어요.', bp.created_at + interval '77 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.homecook@example.com' and bp.title = '퇴근하고 20분 안에 만드는 저녁, 다들 뭐 드세요?' and u.email = 'demo.mukja@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '냉동실에 볶음밥 소스를 얼음틀에 얼려 두면 밥만 볶으면 돼요. 이거 하고 나서 배달이 반으로 줄었어요.');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '베란다에서 키운 바질로 바질 페스토 파스타! 자랑하고 싶어서 남깁니다 🌿', bp.created_at + interval '130 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.homecook@example.com' and bp.title = '퇴근하고 20분 안에 만드는 저녁, 다들 뭐 드세요?' and u.email = 'demo.plant@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '베란다에서 키운 바질로 바질 페스토 파스타! 자랑하고 싶어서 남깁니다 🌿');
update board_post set comment_count = (select count(*) from board_comment c where c.board_post_id = board_post.board_post_id) where board_post_id = (select bp.board_post_id from board_post bp join users a on a.users_id = bp.users_id where a.email = 'demo.homecook@example.com' and bp.title = '퇴근하고 20분 안에 만드는 저녁, 다들 뭐 드세요?');

-- React 19 폼 액션, 기존 onSubmit 코드에서 옮길 만한가요?
insert into board_post (users_id, topic_id, kind, title, content, views, comment_count, created_at, updated_at) select u.users_id, t.topic_id, 'question', 'React 19 폼 액션, 기존 onSubmit 코드에서 옮길 만한가요?', '사내 관리 화면이 전부 `onSubmit` + `useState`로 되어 있어요. 폼이 40개쯤 됩니다.

`useActionState`로 옮기면 로딩·오류 상태 코드가 줄어드는 건 알겠는데,

1. 서버 액션 없이 클라이언트에서만 써도 이점이 있는지
2. 한 번에 다 옮기는 게 나은지, 새 화면부터 쓰는 게 나은지

써 보신 분들 경험이 궁금합니다.', 318, 0, now() - interval '20 hours', now() - interval '20 hours' from users u, topic t where u.email = 'demo.frontnote@example.com' and t.topic_name = '개발' and not exists (select 1 from board_post bp where bp.users_id = u.users_id and bp.title = 'React 19 폼 액션, 기존 onSubmit 코드에서 옮길 만한가요?');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '클라이언트만 써도 pending 상태와 마지막 결과를 한 곳에서 받는 게 꽤 편해요. 다만 40개를 한 번에 옮기진 마시고, 오류 처리가 복잡한 폼부터 두세 개 옮겨 보면서 팀 규칙을 정하는 걸 추천해요. 저희는 공통 훅 하나 만들고 나서 속도가 붙었어요.', bp.created_at + interval '35 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.frontnote@example.com' and bp.title = 'React 19 폼 액션, 기존 onSubmit 코드에서 옮길 만한가요?' and u.email = 'demo.codecup@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '클라이언트만 써도 pending 상태와 마지막 결과를 한 곳에서 받는 게 꽤 편해요. 다만 40개를 한 번에 옮기진 마시고, 오류 처리가 복잡한 폼부터 두세 개 옮겨 보면서 팀 규칙을 정하는 걸 추천해요. 저희는 공통 훅 하나 만들고 나서 속도가 붙었어요.');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '개발은 잘 모르지만 ''새 화면부터''가 늘 정답이더라고요 (사진 보정 프리셋 바꿀 때도요 ㅎㅎ)', bp.created_at + interval '140 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.frontnote@example.com' and bp.title = 'React 19 폼 액션, 기존 onSubmit 코드에서 옮길 만한가요?' and u.email = 'demo.film@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '개발은 잘 모르지만 ''새 화면부터''가 늘 정답이더라고요 (사진 보정 프리셋 바꿀 때도요 ㅎㅎ)');
update board_post set comment_count = (select count(*) from board_comment c where c.board_post_id = board_post.board_post_id) where board_post_id = (select bp.board_post_id from board_post bp join users a on a.users_id = bp.users_id where a.email = 'demo.frontnote@example.com' and bp.title = 'React 19 폼 액션, 기존 onSubmit 코드에서 옮길 만한가요?');
update board_post set accepted_comment_id = (select c.board_comment_id from board_comment c join users u on u.users_id = c.users_id where c.board_post_id = board_post.board_post_id and u.email = 'demo.codecup@example.com' and c.content = '클라이언트만 써도 pending 상태와 마지막 결과를 한 곳에서 받는 게 꽤 편해요. 다만 40개를 한 번에 옮기진 마시고, 오류 처리가 복잡한 폼부터 두세 개 옮겨 보면서 팀 규칙을 정하는 걸 추천해요. 저희는 공통 훅 하나 만들고 나서 속도가 붙었어요.') where board_post_id = (select bp.board_post_id from board_post bp join users a on a.users_id = bp.users_id where a.email = 'demo.frontnote@example.com' and bp.title = 'React 19 폼 액션, 기존 onSubmit 코드에서 옮길 만한가요?') and accepted_comment_id is null;

-- 필름 한 롤 다 찍는 데 다들 얼마나 걸리세요?
insert into board_post (users_id, topic_id, kind, title, content, views, comment_count, created_at, updated_at) select u.users_id, t.topic_id, 'talk', '필름 한 롤 다 찍는 데 다들 얼마나 걸리세요?', '36컷 한 롤을 넣으면 저는 보통 3주쯤 걸려요. 마지막 몇 컷은 꼭 급하게 동네에서 찍게 되고요.

현상소에 맡기고 기다리는 일주일이 제일 설레는 시간인 것 같아요. 여러분은 한 롤에 얼마나 걸리나요?', 96, 0, now() - interval '31 hours', now() - interval '31 hours' from users u, topic t where u.email = 'demo.film@example.com' and t.topic_name = '취미' and not exists (select 1 from board_post bp where bp.users_id = u.users_id and bp.title = '필름 한 롤 다 찍는 데 다들 얼마나 걸리세요?');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '여행 가면 하루에 한 롤, 집에 있으면 두 달이요 😅', bp.created_at + interval '60 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.film@example.com' and bp.title = '필름 한 롤 다 찍는 데 다들 얼마나 걸리세요?' and u.email = 'demo.halfday@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '여행 가면 하루에 한 롤, 집에 있으면 두 달이요 😅');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '바다 갈 때만 들고 가서 한 계절에 한 롤이에요. 그래서 현상하면 계절이 한 번에 지나가요.', bp.created_at + interval '180 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.film@example.com' and bp.title = '필름 한 롤 다 찍는 데 다들 얼마나 걸리세요?' and u.email = 'demo.sea@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '바다 갈 때만 들고 가서 한 계절에 한 롤이에요. 그래서 현상하면 계절이 한 번에 지나가요.');
update board_post set comment_count = (select count(*) from board_comment c where c.board_post_id = board_post.board_post_id) where board_post_id = (select bp.board_post_id from board_post bp join users a on a.users_id = bp.users_id where a.email = 'demo.film@example.com' and bp.title = '필름 한 롤 다 찍는 데 다들 얼마나 걸리세요?');

-- 새벽 러닝 3주째인데 무릎 바깥쪽이 시큰거려요
insert into board_post (users_id, topic_id, kind, title, content, views, comment_count, created_at, updated_at) select u.users_id, t.topic_id, 'question', '새벽 러닝 3주째인데 무릎 바깥쪽이 시큰거려요', '주 3회, 한 번에 5km씩 뛰고 있어요. 처음 2주는 괜찮았는데 이번 주부터 뛰고 나면 무릎 바깥쪽이 시큰합니다.

- 신발은 2년 된 운동화
- 스트레칭은 뛰고 나서만 잠깐

쉬어야 할까요, 거리를 줄이면 될까요?', 187, 0, now() - interval '46 hours', now() - interval '46 hours' from users u, topic t where u.email = 'demo.runner@example.com' and t.topic_name = '운동' and not exists (select 1 from board_post bp where bp.users_id = u.users_id and bp.title = '새벽 러닝 3주째인데 무릎 바깥쪽이 시큰거려요');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '장경인대 쪽일 가능성이 있어요. 며칠은 쉬시고, 엉덩이 옆 근육(중둔근) 운동이랑 폼롤러를 꼭 해 보세요. 신발도 2년이면 쿠션이 많이 죽었을 거예요. 아프면 병원 먼저요!', bp.created_at + interval '25 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.runner@example.com' and bp.title = '새벽 러닝 3주째인데 무릎 바깥쪽이 시큰거려요' and u.email = 'demo.hometrain@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '장경인대 쪽일 가능성이 있어요. 며칠은 쉬시고, 엉덩이 옆 근육(중둔근) 운동이랑 폼롤러를 꼭 해 보세요. 신발도 2년이면 쿠션이 많이 죽었을 거예요. 아프면 병원 먼저요!');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '저도 같은 데가 아팠는데 거리를 반으로 줄이고 케이던스(발 구르는 횟수)를 올리니까 나아졌어요.', bp.created_at + interval '300 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.runner@example.com' and bp.title = '새벽 러닝 3주째인데 무릎 바깥쪽이 시큰거려요' and u.email = 'demo.codecup@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '저도 같은 데가 아팠는데 거리를 반으로 줄이고 케이던스(발 구르는 횟수)를 올리니까 나아졌어요.');
update board_post set comment_count = (select count(*) from board_comment c where c.board_post_id = board_post.board_post_id) where board_post_id = (select bp.board_post_id from board_post bp join users a on a.users_id = bp.users_id where a.email = 'demo.runner@example.com' and bp.title = '새벽 러닝 3주째인데 무릎 바깥쪽이 시큰거려요');
update board_post set accepted_comment_id = (select c.board_comment_id from board_comment c join users u on u.users_id = c.users_id where c.board_post_id = board_post.board_post_id and u.email = 'demo.hometrain@example.com' and c.content = '장경인대 쪽일 가능성이 있어요. 며칠은 쉬시고, 엉덩이 옆 근육(중둔근) 운동이랑 폼롤러를 꼭 해 보세요. 신발도 2년이면 쿠션이 많이 죽었을 거예요. 아프면 병원 먼저요!') where board_post_id = (select bp.board_post_id from board_post bp join users a on a.users_id = bp.users_id where a.email = 'demo.runner@example.com' and bp.title = '새벽 러닝 3주째인데 무릎 바깥쪽이 시큰거려요') and accepted_comment_id is null;

-- 주말 두 번 걸려 만든 첫 책장, 자랑 좀 할게요
insert into board_post (users_id, topic_id, kind, title, content, views, comment_count, created_at, updated_at) select u.users_id, t.topic_id, 'talk', '주말 두 번 걸려 만든 첫 책장, 자랑 좀 할게요', '소나무 집성목으로 5단 책장을 만들었어요. 높이 150cm, 폭 80cm.

처음이라 선반 수평이 1mm씩 안 맞아서 대패로 한참 다듬었습니다. 오일 마감은 두 번 했어요.

다음엔 서랍 달린 협탁에 도전해 보려고요. 서랍 레일 처음 다는 분들께 팁이 있으면 부탁드려요!', 154, 0, now() - interval '70 hours', now() - interval '70 hours' from users u, topic t where u.email = 'demo.woodwork@example.com' and t.topic_name = '취미' and not exists (select 1 from board_post bp where bp.users_id = u.users_id and bp.title = '주말 두 번 걸려 만든 첫 책장, 자랑 좀 할게요');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '와 첫 작품이 5단이라니요! 화분 올려 두면 정말 예쁠 것 같아요.', bp.created_at + interval '45 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.woodwork@example.com' and bp.title = '주말 두 번 걸려 만든 첫 책장, 자랑 좀 할게요' and u.email = 'demo.plant@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '와 첫 작품이 5단이라니요! 화분 올려 두면 정말 예쁠 것 같아요.');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '오일 마감 색이 궁금해요. 사진으로 보고 싶네요 🙂', bp.created_at + interval '120 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.woodwork@example.com' and bp.title = '주말 두 번 걸려 만든 첫 책장, 자랑 좀 할게요' and u.email = 'demo.bakery@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '오일 마감 색이 궁금해요. 사진으로 보고 싶네요 🙂');
update board_post set comment_count = (select count(*) from board_comment c where c.board_post_id = board_post.board_post_id) where board_post_id = (select bp.board_post_id from board_post bp join users a on a.users_id = bp.users_id where a.email = 'demo.woodwork@example.com' and bp.title = '주말 두 번 걸려 만든 첫 책장, 자랑 좀 할게요');

-- 미니오븐(23L)으로 바게트 굽기, 가능할까요?
insert into board_post (users_id, topic_id, kind, title, content, views, comment_count, created_at, updated_at) select u.users_id, t.topic_id, 'question', '미니오븐(23L)으로 바게트 굽기, 가능할까요?', '식빵이랑 스콘은 잘 되는데 바게트는 늘 겉이 딱딱하지 않고 하얗게 나와요.

최고 온도가 230도까지라서 그런 걸까요? 스팀은 분무기로 몇 번 뿌리고 있어요.', 133, 0, now() - interval '94 hours', now() - interval '94 hours' from users u, topic t where u.email = 'demo.bakery@example.com' and t.topic_name = '음식' and not exists (select 1 from board_post bp where bp.users_id = u.users_id and bp.title = '미니오븐(23L)으로 바게트 굽기, 가능할까요?');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '오븐 바닥에 빈 팬을 넣고 같이 예열했다가, 반죽 넣을 때 끓는 물을 붓는 방식으로 바꿔 보세요. 분무기보다 스팀이 훨씬 오래 가요. 길이는 오븐에 맞게 30cm 정도로 짧게요!', bp.created_at + interval '70 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.bakery@example.com' and bp.title = '미니오븐(23L)으로 바게트 굽기, 가능할까요?' and u.email = 'demo.homecook@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '오븐 바닥에 빈 팬을 넣고 같이 예열했다가, 반죽 넣을 때 끓는 물을 붓는 방식으로 바꿔 보세요. 분무기보다 스팀이 훨씬 오래 가요. 길이는 오븐에 맞게 30cm 정도로 짧게요!');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '짧은 바게트도 귀엽고 좋아요. 잘 되면 사진 올려 주세요!', bp.created_at + interval '210 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.bakery@example.com' and bp.title = '미니오븐(23L)으로 바게트 굽기, 가능할까요?' and u.email = 'demo.mukja@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '짧은 바게트도 귀엽고 좋아요. 잘 되면 사진 올려 주세요!');
update board_post set comment_count = (select count(*) from board_comment c where c.board_post_id = board_post.board_post_id) where board_post_id = (select bp.board_post_id from board_post bp join users a on a.users_id = bp.users_id where a.email = 'demo.bakery@example.com' and bp.title = '미니오븐(23L)으로 바게트 굽기, 가능할까요?');
