-- 매일 한 문단씩 쓰기 30일, 해 보신 분 있나요?
insert into board_post (users_id, topic_id, kind, title, content, views, comment_count, created_at, updated_at) select u.users_id, t.topic_id, 'talk', '매일 한 문단씩 쓰기 30일, 해 보신 분 있나요?', '개발 블로그를 쓰고 싶은데 한 편을 다 쓰려고 하면 늘 미루게 되더라고요.

그래서 이번 달은 **하루 한 문단**만 쓰기로 했어요. 글결 잔디가 칸칸이 채워지는 게 은근히 동기부여가 됩니다.

같이 하실 분? 하루에 쓴 문단 길이(원고지 매수)도 같이 남겨 봐요.', 265, 0, now() - interval '120 hours', now() - interval '120 hours' from users u, topic t where u.email = 'demo.codecup@example.com' and t.topic_name = '개발' and not exists (select 1 from board_post bp where bp.users_id = u.users_id and bp.title = '매일 한 문단씩 쓰기 30일, 해 보신 분 있나요?');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '저도 할게요! 오늘은 원고지 1.8매 썼어요 ✍️', bp.created_at + interval '30 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.codecup@example.com' and bp.title = '매일 한 문단씩 쓰기 30일, 해 보신 분 있나요?' and u.email = 'demo.frontnote@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '저도 할게요! 오늘은 원고지 1.8매 썼어요 ✍️');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '러닝 일지로 참여합니다. 뛰는 것보다 쓰는 게 더 어렵네요.', bp.created_at + interval '95 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.codecup@example.com' and bp.title = '매일 한 문단씩 쓰기 30일, 해 보신 분 있나요?' and u.email = 'demo.runner@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '러닝 일지로 참여합니다. 뛰는 것보다 쓰는 게 더 어렵네요.');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '식물 관찰 일기로 같이 할게요. 30일 뒤에 다 같이 회고 글 써요!', bp.created_at + interval '260 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.codecup@example.com' and bp.title = '매일 한 문단씩 쓰기 30일, 해 보신 분 있나요?' and u.email = 'demo.plant@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '식물 관찰 일기로 같이 할게요. 30일 뒤에 다 같이 회고 글 써요!');
