-- 베란다 몬스테라 아래쪽 잎이 노랗게 변해요
insert into board_post (users_id, topic_id, kind, title, content, views, comment_count, created_at, updated_at) select u.users_id, t.topic_id, 'question', '베란다 몬스테라 아래쪽 잎이 노랗게 변해요', '들인 지 1년 된 몬스테라예요. 최근에 아래쪽 큰 잎 두 장이 노래지더니 끝이 갈색으로 마르고 있어요.

물은 겉흙이 마르면 주고 있고, 베란다라 요즘 밤에는 꽤 쌀쌀합니다. 분갈이는 아직 안 했어요.', 109, 0, now() - interval '150 hours', now() - interval '150 hours' from users u, topic t where u.email = 'demo.plant@example.com' and t.topic_name = '취미' and not exists (select 1 from board_post bp where bp.users_id = u.users_id and bp.title = '베란다 몬스테라 아래쪽 잎이 노랗게 변해요');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '저희 집도 가을에 그랬는데 밤 기온 때문이었어요. 밤에는 거실 안으로 들여놓으니까 새 잎이 다시 났어요. 아래 잎은 원래 하나씩 지기도 한대요.', bp.created_at + interval '100 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.plant@example.com' and bp.title = '베란다 몬스테라 아래쪽 잎이 노랗게 변해요' and u.email = 'demo.woodwork@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '저희 집도 가을에 그랬는데 밤 기온 때문이었어요. 밤에는 거실 안으로 들여놓으니까 새 잎이 다시 났어요. 아래 잎은 원래 하나씩 지기도 한대요.');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '1년이면 뿌리가 꽉 찼을 수도 있어요. 화분 밑으로 뿌리 나왔나 한번 보세요!', bp.created_at + interval '400 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.plant@example.com' and bp.title = '베란다 몬스테라 아래쪽 잎이 노랗게 변해요' and u.email = 'demo.homecook@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '1년이면 뿌리가 꽉 찼을 수도 있어요. 화분 밑으로 뿌리 나왔나 한번 보세요!');
update board_post set comment_count = (select count(*) from board_comment c where c.board_post_id = board_post.board_post_id) where board_post_id = (select bp.board_post_id from board_post bp join users a on a.users_id = bp.users_id where a.email = 'demo.plant@example.com' and bp.title = '베란다 몬스테라 아래쪽 잎이 노랗게 변해요');
update board_post set accepted_comment_id = (select c.board_comment_id from board_comment c join users u on u.users_id = c.users_id where c.board_post_id = board_post.board_post_id and u.email = 'demo.woodwork@example.com' and c.content = '저희 집도 가을에 그랬는데 밤 기온 때문이었어요. 밤에는 거실 안으로 들여놓으니까 새 잎이 다시 났어요. 아래 잎은 원래 하나씩 지기도 한대요.') where board_post_id = (select bp.board_post_id from board_post bp join users a on a.users_id = bp.users_id where a.email = 'demo.plant@example.com' and bp.title = '베란다 몬스테라 아래쪽 잎이 노랗게 변해요') and accepted_comment_id is null;

-- 동해 일출, 구름 낀 날이 오히려 좋았던 이야기
insert into board_post (users_id, topic_id, kind, title, content, views, comment_count, created_at, updated_at) select u.users_id, t.topic_id, 'talk', '동해 일출, 구름 낀 날이 오히려 좋았던 이야기', '새벽 5시에 일어나 나갔는데 수평선에 구름이 두껍게 껴 있어서 반쯤 포기했어요.

그런데 해가 구름 위로 올라오는 순간, 구름 가장자리가 전부 주황색으로 타오르더라고요. 맑은 날보다 훨씬 오래 하늘이 물들어 있었습니다.

여러분의 ''날씨가 망했는데 오히려 좋았던 여행''도 듣고 싶어요.', 176, 0, now() - interval '200 hours', now() - interval '200 hours' from users u, topic t where u.email = 'demo.sea@example.com' and t.topic_name = '여행' and not exists (select 1 from board_post bp where bp.users_id = u.users_id and bp.title = '동해 일출, 구름 낀 날이 오히려 좋았던 이야기');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '그런 하늘은 필름으로 찍으면 진짜 예뻐요. 다음엔 꼭 같이 가고 싶네요.', bp.created_at + interval '50 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.sea@example.com' and bp.title = '동해 일출, 구름 낀 날이 오히려 좋았던 이야기' and u.email = 'demo.film@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '그런 하늘은 필름으로 찍으면 진짜 예뻐요. 다음엔 꼭 같이 가고 싶네요.');
insert into board_comment (board_post_id, users_id, content, created_at) select bp.board_post_id, u.users_id, '제주에서 태풍 때문에 비행기가 하루 밀렸는데, 그 덕에 간 동네 국숫집이 여행 최고의 기억이에요 ㅎㅎ', bp.created_at + interval '160 minutes' from board_post bp join users a on a.users_id = bp.users_id, users u where a.email = 'demo.sea@example.com' and bp.title = '동해 일출, 구름 낀 날이 오히려 좋았던 이야기' and u.email = 'demo.halfday@example.com' and not exists (select 1 from board_comment c where c.board_post_id = bp.board_post_id and c.users_id = u.users_id and c.content = '제주에서 태풍 때문에 비행기가 하루 밀렸는데, 그 덕에 간 동네 국숫집이 여행 최고의 기억이에요 ㅎㅎ');
update board_post set comment_count = (select count(*) from board_comment c where c.board_post_id = board_post.board_post_id) where board_post_id = (select bp.board_post_id from board_post bp join users a on a.users_id = bp.users_id where a.email = 'demo.sea@example.com' and bp.title = '동해 일출, 구름 낀 날이 오히려 좋았던 이야기');

